class Solution:
    def maxDifference(self, s: str) -> int:
        freq = [0] * 26

        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        max_odd = 0
        min_even = 101

        for count in freq:
            if count == 0:
                continue

            if count % 2 == 0:
                min_even = min(min_even, count)
            else:
                max_odd = max(max_odd, count)

        return max_odd - min_even
